// cur when every cluster that reported is priced from the bill, partial when some are, pending when none is yet but the bill has priced them before, none otherwise
type FleetSummaryCostBasis string

const (
	FleetSummaryCostBasisCur     FleetSummaryCostBasis = "cur"
	FleetSummaryCostBasisPartial FleetSummaryCostBasis = "partial"
	FleetSummaryCostBasisPending FleetSummaryCostBasis = "pending"
	FleetSummaryCostBasisNone    FleetSummaryCostBasis = "none"
)

func NewFleetSummaryCostBasisFromString(s string) (FleetSummaryCostBasis, error) {
	switch s {
	case "cur":
		return FleetSummaryCostBasisCur, nil
	case "partial":
		return FleetSummaryCostBasisPartial, nil
	case "pending":
		return FleetSummaryCostBasisPending, nil
	case "none":
		return FleetSummaryCostBasisNone, nil
	}
	var t FleetSummaryCostBasis
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (f FleetSummaryCostBasis) Ptr() *FleetSummaryCostBasis {
	return &f
}

