type NamespaceItemKind string

const (
	NamespaceItemKindNamespace NamespaceItemKind = "namespace"
	NamespaceItemKindIdle      NamespaceItemKind = "idle"
	NamespaceItemKindSystem    NamespaceItemKind = "system"
	NamespaceItemKindNode      NamespaceItemKind = "node"
)

func NewNamespaceItemKindFromString(s string) (NamespaceItemKind, error) {
	switch s {
	case "namespace":
		return NamespaceItemKindNamespace, nil
	case "idle":
		return NamespaceItemKindIdle, nil
	case "system":
		return NamespaceItemKindSystem, nil
	case "node":
		return NamespaceItemKindNode, nil
	}
	var t NamespaceItemKind
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (n NamespaceItemKind) Ptr() *NamespaceItemKind {
	return &n
}

