// From the bill when priced, else from the label
type NodeItemPurchaseType string

const (
	NodeItemPurchaseTypeSpot        NodeItemPurchaseType = "spot"
	NodeItemPurchaseTypeOnDemand    NodeItemPurchaseType = "on_demand"
	NodeItemPurchaseTypeReserved    NodeItemPurchaseType = "reserved"
	NodeItemPurchaseTypeSavingsPlan NodeItemPurchaseType = "savings_plan"
	NodeItemPurchaseTypeUnknown     NodeItemPurchaseType = "unknown"
)

func NewNodeItemPurchaseTypeFromString(s string) (NodeItemPurchaseType, error) {
	switch s {
	case "spot":
		return NodeItemPurchaseTypeSpot, nil
	case "on_demand":
		return NodeItemPurchaseTypeOnDemand, nil
	case "reserved":
		return NodeItemPurchaseTypeReserved, nil
	case "savings_plan":
		return NodeItemPurchaseTypeSavingsPlan, nil
	case "unknown":
		return NodeItemPurchaseTypeUnknown, nil
	}
	var t NodeItemPurchaseType
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (n NodeItemPurchaseType) Ptr() *NodeItemPurchaseType {
	return &n
}

