type SavedByProviderItem struct {
	// Realized savings audit row id
	AuditID int `json:"audit_id" url:"audit_id"`
	// Recommendation id
	RecommendationID string `json:"recommendation_id" url:"recommendation_id"`
	// User-facing savings identifier (alias of recommendation_id)
	SavingsID string `json:"savings_id" url:"savings_id"`
	// Period in YYYY-MM format
	Period string `json:"period" url:"period"`
	// ISO 8601 timestamp of the cloud event that realized the savings
	ImplementedAt *string `json:"implemented_at,omitempty" url:"implemented_at,omitempty"`
	// Cloud account ID
	AccountID *string `json:"account_id,omitempty" url:"account_id,omitempty"`
	// Environment. Holds the account alias rather than a fixed vocabulary, e.g. payments-prod, aws.data.staging, production-web, Shared-Services.
	Environment *string `json:"environment,omitempty" url:"environment,omitempty"`
	// Provider identifier: aws, gcp, azure, k8s
	Provider string `json:"provider" url:"provider"`
	// Resource/service name - maps to Resource column in UI
	Service string `json:"service" url:"service"`
	// Usage type description; null when no Cost Explorer line item is available
	UsageType *string `json:"usage_type,omitempty" url:"usage_type,omitempty"`
	// Usage quantity; null when no Cost Explorer line item is available
	UsageQuantity *float64 `json:"usage_quantity,omitempty" url:"usage_quantity,omitempty"`
	// Usage unit; null when no Cost Explorer line item is available
	UsageUnit *string `json:"usage_unit,omitempty" url:"usage_unit,omitempty"`
	// Pre-optimization cost (derived in v1)
	Cost float64 `json:"cost" url:"cost"`
	// Realized savings (alias of realized_savings_usd)
	Savings float64 `json:"savings" url:"savings"`
	// Legacy alias of approved_by (saving_accepted_by, falls back to actor_principal); kept for older clients
	Author *string `json:"author,omitempty" url:"author,omitempty"`
	// Member who requested the execution (execution_request_by); null when there was no explicit requester
	RequestedBy *string `json:"requested_by,omitempty" url:"requested_by,omitempty"`
	// Dashboard user who approved the savings (saving_accepted_by); falls back to actor_principal
	ApprovedBy *string `json:"approved_by,omitempty" url:"approved_by,omitempty"`
	// How the apply was attributed (sourced from implementation_method)
	AppliedVia string `json:"applied_via" url:"applied_via"`
	// How the rec was implemented: one-click / one-click-plus-iac / iac / manual
	ImplementationMethod *string `json:"implementation_method,omitempty" url:"implementation_method,omitempty"`
	// Earliest view of this rec on any channel (manual path)
	FirstViewAt *string `json:"first_view_at,omitempty" url:"first_view_at,omitempty"`
	// Channel of the earliest view: dashboard / cli / sdk-go / sdk-node / sdk-python / api
	FirstViewChannel *string `json:"first_view_channel,omitempty" url:"first_view_channel,omitempty"`
	// Total view count snapshot at audit reconcile time
	ViewCountAtAudit *int `json:"view_count_at_audit,omitempty" url:"view_count_at_audit,omitempty"`
	// Verification state: pending / auto-by-worker / auto-by-worker-and-iac / auto-by-iac / auto-wizard-manual / manual-verified / manual-unverified
	Verification *string `json:"verification,omitempty" url:"verification,omitempty"`
	// Estimated savings at apply time
	EstimatedSavingsUsd *float64 `json:"estimated_savings_usd,omitempty" url:"estimated_savings_usd,omitempty"`
	// Settled realized savings for this line; null while the billing period is open or before settlement
	RealizedSavingsUsd *float64 `json:"realized_savings_usd,omitempty" url:"realized_savings_usd,omitempty"`
	// Running CE-visible realized savings during an open billing period; finalized into realized_savings_usd ≥5 days after period end
	RealizedSavingsInProgressUsd *float64 `json:"realized_savings_in_progress_usd,omitempty" url:"realized_savings_in_progress_usd,omitempty"`
	// Timestamp at which realized_savings_usd was finalized for this period
	SettledAt *string `json:"settled_at,omitempty" url:"settled_at,omitempty"`
	// Reconciliation snapshot 7 days post-apply (CE-driven)
	RealizedSavings7DUsd *float64 `json:"realized_savings_7d_usd,omitempty" url:"realized_savings_7d_usd,omitempty"`
	// Reconciliation snapshot 30 days post-apply (CE-driven, billable)
	RealizedSavings30DUsd *float64 `json:"realized_savings_30d_usd,omitempty" url:"realized_savings_30d_usd,omitempty"`
	// Timestamp the 7-day snapshot was taken
	Snapshot7DAt *string `json:"snapshot_7d_at,omitempty" url:"snapshot_7d_at,omitempty"`
	// Timestamp the 30-day snapshot was taken
	Snapshot30DAt *string `json:"snapshot_30d_at,omitempty" url:"snapshot_30d_at,omitempty"`
	// Source for realized savings calculation
	RealizedBasis string `json:"realized_basis" url:"realized_basis"`

	// Private bitmask of fields set to an explicit value and therefore not to be omitted
	explicitFields *big.Int `json:"-" url:"-"`

	extraProperties map[string]interface{}
	rawJSON         json.RawMessage
}

