type WorkloadEventType string

const (
	WorkloadEventTypeOomKill   WorkloadEventType = "oom_kill"
	WorkloadEventTypeRestart   WorkloadEventType = "restart"
	WorkloadEventTypeThrottled WorkloadEventType = "throttled"
	WorkloadEventTypeEviction  WorkloadEventType = "eviction"
	WorkloadEventTypePrOpened  WorkloadEventType = "pr_opened"
	WorkloadEventTypePrMerged  WorkloadEventType = "pr_merged"
	WorkloadEventTypeRolledOut WorkloadEventType = "rolled_out"
	WorkloadEventTypeVerified  WorkloadEventType = "verified"
	WorkloadEventTypeRegressed WorkloadEventType = "regressed"
	WorkloadEventTypeReverted  WorkloadEventType = "reverted"
	WorkloadEventTypeStale     WorkloadEventType = "stale"
)

func NewWorkloadEventTypeFromString(s string) (WorkloadEventType, error) {
	switch s {
	case "oom_kill":
		return WorkloadEventTypeOomKill, nil
	case "restart":
		return WorkloadEventTypeRestart, nil
	case "throttled":
		return WorkloadEventTypeThrottled, nil
	case "eviction":
		return WorkloadEventTypeEviction, nil
	case "pr_opened":
		return WorkloadEventTypePrOpened, nil
	case "pr_merged":
		return WorkloadEventTypePrMerged, nil
	case "rolled_out":
		return WorkloadEventTypeRolledOut, nil
	case "verified":
		return WorkloadEventTypeVerified, nil
	case "regressed":
		return WorkloadEventTypeRegressed, nil
	case "reverted":
		return WorkloadEventTypeReverted, nil
	case "stale":
		return WorkloadEventTypeStale, nil
	}
	var t WorkloadEventType
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (w WorkloadEventType) Ptr() *WorkloadEventType {
	return &w
}

